CREATE TABLE IF NOT EXISTS patients (id SERIAL PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(30) NOT NULL, date_of_birth DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS doctors (id SERIAL PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, specialty VARCHAR(120) NOT NULL, license_number VARCHAR(80) UNIQUE NOT NULL, phone VARCHAR(30), bio TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY, appointment_id VARCHAR(20) UNIQUE NOT NULL, queue_token INTEGER NOT NULL, appointment_date DATE NOT NULL, appointment_time TIME NOT NULL, reason TEXT NOT NULL, fee NUMERIC(10,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Confirmed', patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE, doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT unique_doctor_slot UNIQUE (doctor_id, appointment_date, appointment_time));
CREATE TABLE IF NOT EXISTS prescriptions (id SERIAL PRIMARY KEY, medicines TEXT NOT NULL, instructions TEXT NOT NULL, issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), appointment_id INTEGER UNIQUE NOT NULL REFERENCES appointments(id) ON DELETE CASCADE, doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS admins (id SERIAL PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_appointments_patient ON appointments(patient_id); CREATE INDEX IF NOT EXISTS idx_appointments_doctor_date ON appointments(doctor_id, appointment_date);
